import{Ft as e,St as t,bt as n,ht as r,t as i,vt as a,xt as o,zt as s}from"./chunks/framework.B0CLzZNn.js";import"./chunks/assets.2zH0uHwH.js";var c=JSON.parse(`{"title":"多模态服务 (Multimodal Service)","description":"","frontmatter":{},"headers":[],"relativePath":"ecosystem/plugin/multimodal-service.md","filePath":"v1/ecosystem/plugin/multimodal-service.md","lastUpdated":1793342047000}`),l={name:`ecosystem/plugin/multimodal-service.md`};function u(i,c,l,u,d,f){let p=s(`NolebasePageProperties`),m=s(`NolebaseGitChangelog`);return e(),a(`div`,null,[c[0]||=r(`h1`,{id:`多模态服务-multimodal-service`,tabindex:`-1`},[o(`多模态服务 (Multimodal Service) `),r(`a`,{class:`header-anchor`,href:`#多模态服务-multimodal-service`,"aria-label":`Permalink to “多模态服务 (Multimodal Service)”`},`​`)],-1),t(p),c[1]||=n(`<p>此插件为 ChatLuna 提供多模态支持，包括上下文图像/语音描述、GIF 处理与 <code>read_files</code> 文件读取工具。为不支持图像/音频多模态的模型提供多模态识别能力，并支持将不支持的音频格式转码后注入上下文。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h2><ul><li>前往插件市场搜索 <code>chatluna-multimodal-service</code> 并安装。</li></ul><p><img src="/images/image-82.png" alt="alt text" width="1002" height="404" loading="lazy"></p><ul><li><p>安装完成后，参考下面的插件配置，配置插件。</p></li><li><p>启用插件。</p></li></ul><h2 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h2><p>确保配置插件后，启用插件即可。</p><p>插件主要提供以下能力：</p><h3 id="上下文图像描述服务" tabindex="-1">上下文图像描述服务 <a class="header-anchor" href="#上下文图像描述服务" aria-label="Permalink to “上下文图像描述服务”">​</a></h3><p>为上下文中的图像提前生成文本描述，使不支持图像输入的模型可以直接在对话历史记录中看到图像对应的文本描述。</p><p>若当前模型本身支持图像输入，则会直接将图像（GIF 会被拆分为帧）注入上下文，不经过描述模型。</p><h3 id="音频转码注入" tabindex="-1">音频转码注入 <a class="header-anchor" href="#音频转码注入" aria-label="Permalink to “音频转码注入”">​</a></h3><p>当模型支持音频输入但接收到的音频格式不被原生支持时（如 Silk、AMR 等），会通过 ffmpeg 转码为 MP3 后再注入上下文。主要针对语音消息。</p><h3 id="文件读取-描述工具-read-files" tabindex="-1">文件读取/描述工具 (<code>read_files</code>) <a class="header-anchor" href="#文件读取-描述工具-read-files" aria-label="Permalink to “文件读取/描述工具 (read_files)”">​</a></h3><p>允许模型调用 <code>read_files</code> 工具读取 URL 中的图像（如工具返回的图像 URL）、文件内容，并根据读取的内容回答用户的问题。</p><p>支持读取的文件类型包括：图像（BMP、JPEG、PNG、WebP、GIF）、纯文本、Markdown、HTML、JSON、PDF、音频、视频等（具体取决于模型能力）。</p><div class="tip custom-block github-alert"><p class="custom-block-title">提示</p><p>建议搭配 <code>chatluna-storage-service</code> 使用。请求中的图像、文件大小限制遵循模型平台配置（如 Gemini：PDF 单文件 50MB、其他单文件 100MB、单轮总计 100MB，以文件被编码为 Base64 后的大小为准）。</p></div><h2 id="配置项" tabindex="-1">配置项 <a class="header-anchor" href="#配置项" aria-label="Permalink to “配置项”">​</a></h2><p>此处列举了 <code>chatluna-multimodal-service</code> 插件的配置项。</p><h3 id="上下文图像描述服务设置" tabindex="-1">上下文图像描述服务设置 <a class="header-anchor" href="#上下文图像描述服务设置" aria-label="Permalink to “上下文图像描述服务设置”">​</a></h3><h4 id="enablecontextimagedescription" tabindex="-1">enableContextImageDescription <a class="header-anchor" href="#enablecontextimagedescription" aria-label="Permalink to “enableContextImageDescription”">​</a></h4><ul><li>类型：<code>boolean</code></li><li>默认值：<code>false</code></li></ul><p>是否为上下文中的图像使用图像描述服务生成并注入文本描述。仅当前模型不支持图像输入时生效。</p><h4 id="enablecontextgifhandling" tabindex="-1">enableContextGifHandling <a class="header-anchor" href="#enablecontextgifhandling" aria-label="Permalink to “enableContextGifHandling”">​</a></h4><ul><li>类型：<code>boolean</code></li><li>默认值：<code>false</code></li></ul><p>是否为上下文中的 GIF 使用图像描述服务生成并注入文本描述。关闭后 GIF 将被从上下文中移除。</p><h3 id="文件读取-描述工具设置" tabindex="-1">文件读取/描述工具设置 <a class="header-anchor" href="#文件读取-描述工具设置" aria-label="Permalink to “文件读取/描述工具设置”">​</a></h3><h4 id="enableimagereadtool" tabindex="-1">enableImageReadTool <a class="header-anchor" href="#enableimagereadtool" aria-label="Permalink to “enableImageReadTool”">​</a></h4><ul><li>类型：<code>boolean</code></li><li>默认值：<code>false</code></li></ul><p>启用 <code>read_files</code> 工具的图像读取/描述功能（非 GIF）。若当前模型不支持图像输入，则会使用图像描述模型生成描述。若当前模型支持图像输入，建议只保留这一个图像读取工具开启，因为它能使模型自己看见图像内容，比图像描述更加精确。</p><h4 id="enablegifreadtool" tabindex="-1">enableGifReadTool <a class="header-anchor" href="#enablegifreadtool" aria-label="Permalink to “enableGifReadTool”">​</a></h4><ul><li>类型：<code>boolean</code></li><li>默认值：<code>false</code></li></ul><p>启用 <code>read_files</code> 工具的 GIF 描述功能。</p><h4 id="enablefilereadtool" tabindex="-1">enableFileReadTool <a class="header-anchor" href="#enablefilereadtool" aria-label="Permalink to “enableFileReadTool”">​</a></h4><ul><li>类型：<code>boolean</code></li><li>默认值：<code>false</code></li></ul><p>启用 <code>read_files</code> 工具的通用文件读取功能（支持纯文本、PDF、JSON、音频、视频等，具体取决于模型能力）。若模型不支持该文件类型输入，则会返回报错。</p><h3 id="音频转换设置" tabindex="-1">音频转换设置 <a class="header-anchor" href="#音频转换设置" aria-label="Permalink to “音频转换设置”">​</a></h3><h4 id="enableaudioffmpegconversion" tabindex="-1">enableAudioFfmpegConversion <a class="header-anchor" href="#enableaudioffmpegconversion" aria-label="Permalink to “enableAudioFfmpegConversion”">​</a></h4><ul><li>类型：<code>boolean</code></li><li>默认值：<code>false</code></li></ul><p>启用不支持音频格式的 ffmpeg 转换。仅当当前模型不原生支持该音频格式时，才会先转码为 MP3 再注入，主要针对语音消息。需要安装并启用 <code>koishi-plugin-ffmpeg-path</code>；其中官方 Bot 的 silk 语音依赖 <code>koishi-plugin-ffmpeg-path</code> 2.0.0 及以上版本提供的 silk 服务。</p><h3 id="文件读取设置" tabindex="-1">文件读取设置 <a class="header-anchor" href="#文件读取设置" aria-label="Permalink to “文件读取设置”">​</a></h3><h4 id="fileinsertprompt" tabindex="-1">fileInsertPrompt <a class="header-anchor" href="#fileinsertprompt" aria-label="Permalink to “fileInsertPrompt”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：<code>以下是通过工具读取的文件内容，请结合这些内容回答用户的问题。</code></li></ul><p>文件内容注入到上下文时的提示词。在注入的文件内容前面追加此提示词，用于引导模型结合文件内容回答问题。</p><h3 id="图像描述服务设置" tabindex="-1">图像描述服务设置 <a class="header-anchor" href="#图像描述服务设置" aria-label="Permalink to “图像描述服务设置”">​</a></h3><h4 id="imagemodel" tabindex="-1">imageModel <a class="header-anchor" href="#imagemodel" aria-label="Permalink to “imageModel”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：<code>无</code></li></ul><p>选择支持图像输入的模型以生成图像描述（如 <code>gemini-3-flash-preview</code>、<code>qwen3.5-flash</code>、<code>doubao-seed-2.0-lite</code>）。</p><h4 id="imageprompt" tabindex="-1">imagePrompt <a class="header-anchor" href="#imageprompt" aria-label="Permalink to “imagePrompt”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：<code>你现在是一个图片描述大师。你需要根据下面提供的图片，对该图片或者图片列表生成 150-400 字的中文描述。包括图片的主要内容和场景，里面可能包含的梗，人物等。</code></li></ul><p>传递给图像描述模型的系统提示词。</p><h4 id="imageinsertprompt" tabindex="-1">imageInsertPrompt <a class="header-anchor" href="#imageinsertprompt" aria-label="Permalink to “imageInsertPrompt”">​</a></h4><ul><li>类型：<code>string</code></li><li>默认值：<code>&lt;img&gt;这是一张图片的描述: {img}。如果用户需要询问一些关于图片的问题，请根据上面的描述回答。如果用户没有提供图片，请忽略上面的描述。&lt;/img&gt;</code></li></ul><p>图像描述插入到具体消息里的提示词。</p><h4 id="gifstrategy" tabindex="-1">gifStrategy <a class="header-anchor" href="#gifstrategy" aria-label="Permalink to “gifStrategy”">​</a></h4><ul><li>类型：<code>&#39;first&#39; | &#39;head&#39; | &#39;average&#39;</code></li><li>默认值：<code>first</code></li></ul><p>GIF 图像帧提取策略：</p><ul><li><code>first</code>：只获取第一帧</li><li><code>head</code>：获取前 N 帧</li><li><code>average</code>：平均获取 N 帧</li></ul><h4 id="gifframecount" tabindex="-1">gifFrameCount <a class="header-anchor" href="#gifframecount" aria-label="Permalink to “gifFrameCount”">​</a></h4><ul><li>类型：<code>number</code></li><li>默认值：<code>3</code></li><li>范围：<code>1-5</code></li></ul><p>提取的帧数（仅在选择 <code>head</code> 或 <code>average</code> 策略时有效）。</p>`,61),t(m)])}var d=i(l,[[`render`,u]]);export{c as __pageData,d as default};